                        var foreignSchema=new byte[32];Arrays.fill(foreignSchema,(byte)7);var schemaSource=new RangeDirectory(current.clusterId(),current.databaseId(),current.domainId(),current.schemaEpoch()+1,foreignSchema,current.generation(),current.columns(),current.routingPrefixBytes(),current.ranges());var schemaTarget=new RangeDirectory(target.clusterId(),target.databaseId(),target.domainId(),target.schemaEpoch()+1,foreignSchema,target.generation(),target.columns(),target.routingPrefixBytes(),target.ranges());var changedSchema=RatisNodeRuntime.sourceRequest(new TopologyChange.Definition(new UUID(211,7),schemaSource,schemaTarget),f.catalogueId,voter);assertThrows(ExecutionException.class,()->machine.query(RatisTopologyLearnerRuntimeTest.message(RatisTopologyLearnerRecoveryRpc.request(changedSchema))).get(5,TimeUnit.SECONDS));assertEquals(captures,f.source.captures.get());assertEquals(unchanged,store.applied());assertNull(store.topologyLearnerImagePermission());
