                        assertThrows(ExecutionException.class,()->machine.query(RatisTopologyLearnerRuntimeTest.message(RatisTopologyLearnerRecoveryRpc.request(request))).get(5,TimeUnit.SECONDS));assertNull(store.topologyLearnerImagePermission());assertEquals(unchanged,store.applied());assertArrayEquals(f.source.schema.digest(),store.schemaDigest());
